def can_commit(acks: int, n: int) -> bool:
    # Crash model: majority = f+1 where f = (n-1)//2
    return acks >= (n // 2 + 1)

def can_commit_byzantine(matching_votes: int, n: int, f: int) -> bool:
    assert n >= 3*f + 1, "unsafe Byzantine sizing"
    return matching_votes >= 2*f + 1

# Example: n=5 crash-tolerant -> need 3 acks, survive 2 crashes
# Example: f=1 byzantine -> need n=4, need 3 matching votes per phase
